[
  {
    "title": "competing-start-cues",
    "claim": "Image 2 displays both a FIGHT button and STARTING IN 2, giving the player simultaneous manual-start and countdown cues.",
    "reason": "A newcomer may feel rushed before understanding the controls.",
    "suggest": "Make the introduction wait for FIGHT; reserve countdowns for transitions after the player has explicitly started."
  },
  {
    "title": "result-combat-poses",
    "claim": "Image 18 announces ASMONGOLD WINS while Asmongold is shown kicking and HasanAbi remains in a standing guard pose.",
    "reason": "The fighter presentation does not reinforce the outcome as clearly as the headline does.",
    "suggest": "Use distinct winner-celebration and loser-defeat poses on the result screen, without changing the scored exchange."
  },
  {
    "title": "empty-desktop-control-band",
    "claim": "Image 9 places the two sticks at opposite ends of a full-width dark band with an empty center beneath the arena.",
    "reason": "The desktop composition gives substantial visual space to an otherwise empty control area.",
    "suggest": "Use compact bottom-corner control panels on desktop and extend the arena into the released space, preserving the portrait-phone layout."
  },
  {
    "title": "input-badges-lack-local-labels",
    "claim": "Image 6 identifies STANCE and TECHNIQUE in the top legend, but the individual move rows contain two input badges without those labels.",
    "reason": "Players must remember the legend's ordering while decoding each move.",
    "suggest": "Add labelled STANCE and TECHNIQUE columns within each technique group, keeping the input badges aligned beneath their respective labels."
  },
  {
    "title": "front-kick-endpoint-unresolved",
    "claim": "In Image 13, the raised leg's endpoint does not show a clearly distinguishable bare-foot silhouette comparable to the planted foot, but the still cannot establish whether the foot is clipped or simply obscured by the pose.",
    "reason": "The striking limb needs a readable silhouette, but an unsupported anatomy correction could damage a valid sprite.",
    "suggest": "Inspect the unscaled source pose, atlas crop boundaries, and a short kick sequence before editing; expand the affected crop only if clipping is confirmed."
  }
]
